--
-- Structure for view `v_action_logs`
--
DROP TABLE IF EXISTS `v_action_logs`;

CREATE ALGORITHM=UNDEFINED DEFINER=`user`@`localhost` SQL SECURITY DEFINER VIEW `v_action_logs`  AS SELECT `al`.`id` AS `id`, `al`.`actionid` AS `actionid`, `al`.`devices_id` AS `devices_id`, `d`.`device_name` AS `device_name`, `da`.`action` AS `action`, `al`.`message` AS `message`, `al`.`version` AS `version`, `al`.`logged_at` AS `logged_at`, `da`.`status` AS `action_status` FROM ((`action_logs` `al` join `device_actions` `da` on(`al`.`actionid` = `da`.`actionid`)) join `device` `d` on(`al`.`devices_id` = `d`.`devices_id`)) ORDER BY `al`.`logged_at` DESC ;

-- --------------------------------------------------------

--
-- Structure for view `v_device_summary`
--
DROP TABLE IF EXISTS `v_device_summary`;

CREATE ALGORITHM=UNDEFINED DEFINER=`user`@`localhost` SQL SECURITY DEFINER VIEW `v_device_summary`  AS SELECT `d`.`devices_id` AS `devices_id`, `d`.`device_name` AS `device_name`, `d`.`firmware_version` AS `firmware_version`, `d`.`status` AS `status`, `d`.`last_sent` AS `last_sent`, `d`.`last_ssid` AS `last_ssid`, `d`.`last_rssi` AS `last_rssi`, `d`.`last_ip` AS `last_ip`, (select count(0) from `device_actions` where `device_actions`.`devices_id` = `d`.`devices_id` and `device_actions`.`status` = 'pending') AS `pending_actions`, (select count(0) from `device_actions` where `device_actions`.`devices_id` = `d`.`devices_id` and `device_actions`.`status` = 'completed') AS `completed_actions`, (select count(0) from `device_actions` where `device_actions`.`devices_id` = `d`.`devices_id` and `device_actions`.`status` = 'failed') AS `failed_actions`, (select count(0) from `heartbeats` where `heartbeats`.`devices_id` = `d`.`devices_id`) AS `total_heartbeats` FROM `device` AS `d` ORDER BY `d`.`last_sent` DESC ;

-- --------------------------------------------------------

--
-- Structure for view `v_pending_actions`
--
DROP TABLE IF EXISTS `v_pending_actions`;

CREATE ALGORITHM=UNDEFINED DEFINER=`user`@`localhost` SQL SECURITY DEFINER VIEW `v_pending_actions`  AS SELECT `da`.`actionid` AS `actionid`, `da`.`devices_id` AS `devices_id`, `d`.`device_name` AS `device_name`, `da`.`action` AS `action`, `da`.`value` AS `value`, `da`.`status` AS `status`, `da`.`created_at` AS `created_at`, `d`.`status` AS `device_status`, `d`.`last_sent` AS `last_sent` FROM (`device_actions` `da` join `device` `d` on(`da`.`devices_id` = `d`.`devices_id`)) WHERE `da`.`status` = 'pending' ORDER BY `da`.`created_at` ASC ;

